//! Ability id -> name, from the game's `abilities.h` `_()` strings.
//!
//! Rows live in `data/ability_names.csv` (generated by
//! `tools/gen_species_meta.py`, which also produces the species/ability table
//! in `species_meta.rs`) and are embedded with `include_str!`, parsed on first
//! use. The id is the ability index the species table stores, not a
//! name-derived value.

use std::sync::OnceLock;

const ABILITY_CSV: &str = include_str!("../data/ability_names.csv");

/// Every ability id the game defines, including id 0, which the game spells
/// "-------" for "no ability".
pub fn ability_names() -> &'static [(u16, &'static str)] {
    static T: OnceLock<Vec<(u16, &'static str)>> = OnceLock::new();
    T.get_or_init(|| crate::csv::parse_named("data/ability_names.csv", ABILITY_CSV))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Look a label up the way the table's own tests need. The accessor the UI uses
    /// is `lookup::ability_name`, which returns `Option`; there is deliberately no
    /// second production accessor here.
    fn label(id: u16) -> &'static str {
        ability_names()
            .iter()
            .find(|(v, _)| *v == id)
            .map(|(_, n)| *n)
            .unwrap_or("<absent>")
    }

    #[test]
    fn ability_table_is_present_sorted_and_anchored() {
        let t = ability_names();
        assert!(t.len() >= 300, "ability names: {} rows", t.len());
        assert_eq!(t[0], (0, "-------"), "id 0 is the game's own blank label");
        assert_eq!(label(1), "Stench");
        assert_eq!(label(3), "Speed Boost");
        assert!(
            t.windows(2).all(|w| w[0].0 < w[1].0),
            "ability ids must increase"
        );
        assert!(
            label(60_000) == "<absent>",
            "an unknown id must have no label in the table"
        );
    }
}
